// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.faceimport timber.log.Timberimport com.roshan.persona.vision.ocr.RgbImageimport com.roshan.persona.vision.ocr.BoundingBoximport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Face Detection Engine (Module 6 v4 — Step 6.4). * * Wraps ML Kit Face Detection for on-device face DETECTION (not recognition). * * ## Hard Privacy Line (per strategy v4 §"Privacy & Security") * *  - **DETECTION ONLY.** NOUS finds faces (bounding boxes + landmarks + contours) *    but NEVER identifies who they are. *  - [FacePrivacyGuard] enforces this — hard-blocks any recognition/identification *    intent. *  - No face-recognition model in the APK. *  - Face-tagging (opt-in × 3 + AES-256 + biometric key) deferred to v5. * * ## What it detects * *  - Face bounding boxes (normalized 0.0-1.0) *  - Facial landmarks (eyes, nose, mouth, ears, cheeks) — for auto-crop alignment *  - Face contours (oval, eyes, eyebrows, lips) — for advanced shape analysis *  - Smile probability (0.0-1.0) — for "smile detection" in photos *  - Eye-open probability (left + right) — for blink detection in portraits *  - Head Euler angles (X, Y, Z) — for frontal face detection * * ## Performance (per strategy v4) * *  - < 80 ms per frame on mid-range devices (ML Kit on-device) *  - < 50 ms on flagship (Snapdragon 8 Gen 2+) *  - Real-time: 12-20 FPS face tracking (vs 30 FPS object detection — face *    detection is heavier per-frame) * * ## Use Cases * *  - **Auto-crop portraits** — detect largest face, crop to face + 20% margin *  - **Smile detection** — "you're all smiling!" in group photos *  - **Blink detection** — "eyes closed, retake?" in portrait mode *  - **Frontal face check** — "please face the camera" for Aadhaar/PAN scans *  - **Group photo count** — "I see 4 people in this photo" * * ## Testability * * Native ML Kit inference is abstracted via [FaceDetectorDelegate] interface. * Production: [MlKitFaceDetectorDelegate] wraps `com.google.mlkit:face-detection`. * Tests: [FakeFaceDetectorDelegate] returns canned face detections. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.4: FaceDetectionEngine</a> */class FaceDetectionEngine(    private val delegate: FaceDetectorDelegate,    private val dispatcher: CoroutineDispatcher,) {    /**     * Detect faces in [frame].     *     * @param frame the input image (RGB).     * @param options detection options (landmarks, contours, classification, etc.).     * @return tiered face detection result.     */    suspend fun detect(        frame: RgbImage,        options: FaceDetectionOptions = FaceDetectionOptions.DEFAULT,    ): TieredFaceResult = withContext(dispatcher) {        // Privacy guard — assert DETECT is allowed (it always is, but this        // documents the check + serves as a code review landmark).        FacePrivacyGuard.assertAllowed(FaceOperation.DETECT)        if (!delegate.isReady()) {            Timber.tag(TAG).w("Face detector not ready — returning empty result.")            val emptyResult = FaceDetectionResult(                faces = emptyList(),                imageWidth = frame.width,                imageHeight = frame.height,                processingTimeMs = 0,            )            return@withContext tieredFaceResult(emptyResult)        }        val startTime = System.currentTimeMillis()        val rawFaces = try {            delegate.detect(frame, options)        } catch (t: Throwable) {            Timber.tag(TAG).e("Face detection failed", t)            emptyList()        }        // Filter by minimum confidence.        val filtered = rawFaces.filter { it.confidence >= options.minConfidence }        val elapsedMs = System.currentTimeMillis() - startTime        val result = FaceDetectionResult(            faces = filtered,            imageWidth = frame.width,            imageHeight = frame.height,            processingTimeMs = elapsedMs,        )        Timber.tag(TAG).d("Face detection: ${rawFaces.size} raw → ${filtered.size} filtered (${elapsedMs}ms).")        tieredFaceResult(result)    }    /**     * Crop an image to the largest face (for portrait auto-crop).     *     * Returns the bounding box to crop to (caller does the actual cropping).     *     * @param frame the input image.     * @param marginPercent margin around the face (e.g., 0.20 = 20% margin).     * @return the crop bounding box, or null if no face detected.     */    suspend fun cropToFace(        frame: RgbImage,        marginPercent: Float = 0.20f,    ): BoundingBox? = withContext(dispatcher) {        FacePrivacyGuard.assertAllowed(FaceOperation.CROP)        val result = detect(frame, FaceDetectionOptions.FAST)        val faces = result.value?.faces ?: return@withContext null        val largest = faces.maxByOrNull { it.boundingBox.area } ?: return@withContext null        // Expand the face box by margin, clamped to [0, 1].        val margin = marginPercent.coerceIn(0f, 1f)        val expandW = largest.boundingBox.width * margin / 2f        val expandH = largest.boundingBox.height * margin / 2f        BoundingBox(            left = (largest.boundingBox.left - expandW).coerceAtLeast(0f),            top = (largest.boundingBox.top - expandH).coerceAtLeast(0f),            right = (largest.boundingBox.right + expandW).coerceAtMost(1f),            bottom = (largest.boundingBox.bottom + expandH).coerceAtMost(1f),        )    }    /**     * Check if all faces in the image are smiling (for group photo "say cheese" mode).     *     * @param frame the input image.     * @return true if at least one face detected AND all are smiling.     */    suspend fun areAllSmiling(frame: RgbImage): Boolean = withContext(dispatcher) {        val result = detect(frame, FaceDetectionOptions(smileDetection = true))        val faces = result.value?.faces ?: return@withContext false        if (faces.isEmpty()) return@withContext false        faces.all { it.isSmiling == true }    }    /**     * Check if any face has eyes closed (for "blink detection" in portraits).     *     * @param frame the input image.     * @return true if at least one face has both eyes closed.     */    suspend fun hasBlink(frame: RgbImage): Boolean = withContext(dispatcher) {        val result = detect(frame, FaceDetectionOptions(eyeOpenDetection = true))        val faces = result.value?.faces ?: return@withContext false        faces.any { face ->            face.leftEyeOpenProbability != null &&            face.rightEyeOpenProbability != null &&            face.leftEyeOpenProbability < 0.3f &&            face.rightEyeOpenProbability < 0.3f        }    }    /**     * Check if the largest face is frontal (for Aadhaar/PAN scan quality).     *     * @param frame the input image.     * @return true if largest face is roughly frontal (|eulerX| < 15° and |eulerY| < 15°).     */    suspend fun isFrontal(frame: RgbImage): Boolean = withContext(dispatcher) {        val result = detect(frame, FaceDetectionOptions.DEFAULT)        val faces = result.value?.faces ?: return@withContext false        val largest = faces.maxByOrNull { it.boundingBox.area } ?: return@withContext false        largest.isFrontal    }    /** True if the detector is ready. */    fun isReady(): Boolean = delegate.isReady()    private companion object {        private const val TAG = "FaceDetectionEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** Face detection options. */data class FaceDetectionOptions(    val minConfidence: Float = 0.50f,    val landmarkExtraction: Boolean = true,    val contourExtraction: Boolean = false,    val smileDetection: Boolean = false,    val eyeOpenDetection: Boolean = false,    val headAngleDetection: Boolean = true,) {    companion object {        /** Default — landmarks + head angles (for auto-crop). */        val DEFAULT = FaceDetectionOptions()        /** Fast — bounding boxes only (for real-time tracking). */        val FAST = FaceDetectionOptions(            landmarkExtraction = false,            headAngleDetection = false,        )        /** Full — all features (for portrait quality check). */        val FULL = FaceDetectionOptions(            contourExtraction = true,            smileDetection = true,            eyeOpenDetection = true,        )    }}// ──────────────────────────────────────────────────────────────────────────/** Face detector delegate interface — abstracts ML Kit for testability. */interface FaceDetectorDelegate {    /** Detect faces in [frame]. Returns raw detections (pre-confidence-filter). */    suspend fun detect(frame: RgbImage, options: FaceDetectionOptions): List<DetectedFace>    /** True if the detector is ready. */    fun isReady(): Boolean}